"""Optional persistent Python cells for model-selected document snapshots.

This is a child process in the same challenge VM, not a nested OS sandbox. It
receives only the selected cleaned HTML as `html` through a bounded JSONL pipe;
Python variables and imports persist per reader until close or timeout. The
model must still select what to inspect before a caller invokes this helper.
"""
import ast
import asyncio
import contextlib
import io
import json
import os
import signal
import sys
import tempfile
import traceback
from pathlib import Path

MAX_HTML = 250_000
MAX_TEXT = 250_000
MAX_CODE = 10_000
MAX_OUTPUT = 4_000
MAX_JSON = 20_000
MAX_CELLS = 8
CELL_SECONDS = 3.0
START_SECONDS = 3.0


class _Output(io.TextIOBase):
    def __init__(self):
        self.parts: list[str] = []
        self.size = 0
        self.truncated = False

    def write(self, value: str) -> int:
        remaining = MAX_OUTPUT - self.size
        if remaining > 0:
            self.parts.append(value[:remaining])
            self.size += min(len(value), remaining)
        if len(value) > remaining:
            self.truncated = True
        return len(value)

    def getvalue(self) -> str:
        return ''.join(self.parts) + ('\n[output truncated]' if self.truncated else '')


def _child() -> None:
    protocol = sys.stdout
    namespace = {'__name__': '__main__', 'state': {}}
    for line in sys.stdin:
        try:
            request = json.loads(line)
            if request.get('cmd') == 'close':
                break
            namespace['html'] = request['html']
            namespace['text'] = request.get('text', '')
            code = request['code']
            want_json = request.get('json', False)
            output = _Output()
            serialized = None
            with contextlib.redirect_stdout(output), contextlib.redirect_stderr(output):
                try:
                    tree = ast.parse(code, mode='exec')
                    if tree.body and isinstance(tree.body[-1], ast.Expr):
                        expression = ast.Expression(tree.body.pop().value)
                        if tree.body:
                            exec(compile(tree, '<model-cell>', 'exec'), namespace)
                        value = eval(compile(expression, '<model-cell>', 'eval'), namespace)
                        if want_json:
                            if value is None:
                                raise ValueError('JSON cell needs a non-None final expression')
                            serialized = json.dumps(value, ensure_ascii=False)
                            if len(serialized.encode('utf-8')) > MAX_JSON:
                                raise ValueError(f'JSON result exceeds {MAX_JSON} bytes')
                        elif value is not None:
                            print(repr(value))
                    else:
                        exec(compile(tree, '<model-cell>', 'exec'), namespace)
                        if want_json:
                            raise ValueError('JSON cell needs a final expression')
                    ok = True
                except BaseException as error:
                    print(''.join(traceback.format_exception_only(type(error), error)).strip())
                    ok = False
            response = {'ok': ok, 'output': output.getvalue(), 'json': serialized}
        except BaseException as error:
            response = {'ok': False, 'output': f'Kernel protocol error: {type(error).__name__}'}
        protocol.write(json.dumps(response, ensure_ascii=False) + '\n')
        protocol.flush()


class PythonKernel:
    """One persistent child process per reader; call `close` in the reader's finally block."""

    def __init__(self, *, cell_seconds: float = CELL_SECONDS):
        self.cell_seconds = cell_seconds
        self.process: asyncio.subprocess.Process | None = None
        self.lock = asyncio.Lock()
        self._tmp: tempfile.TemporaryDirectory | None = None
        self.cells = 0

    async def _start(self) -> None:
        if self.process is not None:
            return
        self._tmp = tempfile.TemporaryDirectory(prefix='selected-python-')
        # -I ignores user site and Python environment variables. No run tokens,
        # website passwords or model keys are passed to the child environment.
        env = {'PATH': os.environ.get('PATH', '/usr/bin:/bin'),
               'HOME': self._tmp.name, 'TMPDIR': self._tmp.name,
               'LANG': os.environ.get('LANG', 'C.UTF-8')}
        try:
            self.process = await asyncio.wait_for(asyncio.create_subprocess_exec(
                sys.executable, '-I', '-u', str(Path(__file__).resolve()), '--child',
                stdin=asyncio.subprocess.PIPE, stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL, cwd=self._tmp.name,
                env=env, start_new_session=True), START_SECONDS)
        except BaseException:
            self._tmp.cleanup()
            self._tmp = None
            raise

    async def _execute(self, html: str, code: str, text: str, want_json: bool) -> dict:
        """Exchange one bounded cell with the persistent child process."""
        if len(html) > MAX_HTML:
            raise ValueError(f'Selected HTML is {len(html)} characters; limit is {MAX_HTML}.')
        if len(text) > MAX_TEXT:
            raise ValueError(f'Selected text is {len(text)} characters; limit is {MAX_TEXT}.')
        if len(code) > MAX_CODE:
            raise ValueError(f'Code is {len(code)} characters; limit is {MAX_CODE}.')
        async with self.lock:
            if self.cells >= MAX_CELLS:
                raise ValueError(f'Workspace reached its {MAX_CELLS}-cell limit.')
            await self._start()
            process = self.process
            if process is None or process.stdin is None or process.stdout is None:
                raise RuntimeError('Python kernel did not start')
            request = json.dumps({'html': html, 'text': text, 'code': code,
                                  'json': want_json}, ensure_ascii=False) + '\n'
            self.cells += 1
            try:
                async with asyncio.timeout(self.cell_seconds):
                    process.stdin.write(request.encode())
                    await process.stdin.drain()
                    line = await process.stdout.readline()
            except (asyncio.TimeoutError, BrokenPipeError, ConnectionResetError, ValueError):
                await self._stop()
                raise ValueError('Python cell timed out or transport failed; workspace reset.')
            if not line:
                await self._stop()
                raise ValueError('Python child exited; workspace reset.')
            try:
                result = json.loads(line)
            except ValueError:
                await self._stop()
                raise ValueError('Python child sent an invalid response; workspace reset.')
            return result

    async def execute(self, html: str, code: str, text: str = '') -> str:
        """Return bounded stdout, a final expression repr, or a short error."""
        try:
            result = await self._execute(html, code, text, False)
        except ValueError as error:
            return str(error)
        return result.get('output', '') or '(no output; print or return an expression)'

    async def execute_json(self, html: str, code: str, text: str = '') -> str:
        """Return only a final expression's JSON for a typed output function."""
        result = await self._execute(html, code, text, True)
        if not result.get('ok'):
            raise ValueError(result.get('output', 'Python cell failed')[:MAX_OUTPUT])
        encoded = result.get('json')
        if not isinstance(encoded, str):
            raise ValueError('Python cell did not return JSON.')
        if len(encoded) > MAX_JSON:
            raise ValueError(f'JSON result is {len(encoded)} characters; limit is {MAX_JSON}.')
        return encoded

    async def _stop(self) -> None:
        process, self.process = self.process, None
        if process is not None:
            if process.returncode is None:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
            try:
                await asyncio.wait_for(process.wait(), 2)
            except asyncio.TimeoutError:
                pass
        if self._tmp is not None:
            self._tmp.cleanup()
            self._tmp = None

    async def close(self) -> None:
        async with self.lock:
            await self._stop()


if __name__ == '__main__' and '--child' in sys.argv:
    _child()
"""Optional model-directed analysis of a selected, inert page snapshot.

The workspace uses a separate context in an already supplied browser. It has no
site cookies, is offline, and never receives a live Page or Playwright handle.
It persists JavaScript `state` across a worker's cells; each cell receives a
fresh DOMParser document for the element the model selected.
"""
import asyncio
import os

from extract import locate
from pydantic import TypeAdapter
from pydantic_ai import ModelRetry, RunContext

from browser_tools import Deps, unseen_values

MAX_SNAPSHOT = 250_000
MAX_OUTPUT = 4_000
MAX_FINAL = 20_000
MAX_CODE = 10_000
MAX_CELLS = 8
CELL_SECONDS = 3
SNAPSHOT_SECONDS = 10

SNAPSHOT_JS = r"""
el => {
  const root = el.cloneNode(true);
  const original = [el, ...el.querySelectorAll('*')];
  const copies = [root, ...root.querySelectorAll('*')];
  const blocked = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'META', 'LINK']);
  const attributes = new Set(['aria-label', 'alt', 'title', 'datetime', 'role',
    'placeholder', 'type', 'value', 'checked', 'selected', 'colspan', 'rowspan', 'data-ar']);
  for (let i = 0; i < original.length; i++) {
    const src = original[i], dst = copies[i];
    if (blocked.has(src.tagName) || src.hidden || src.inert ||
        src.getAttribute('aria-hidden') === 'true' ||
        (src.tagName === 'INPUT' && src.type === 'password') ||
        getComputedStyle(src).display === 'none' ||
        getComputedStyle(src).visibility === 'hidden') {
      dst.remove();
      continue;
    }
    for (const attr of [...dst.attributes]) {
      if (!attributes.has(attr.name))
        dst.removeAttribute(attr.name);
    }
    if (src.tagName === 'INPUT' && src.type !== 'password') dst.setAttribute('value', src.value);
    if (src.tagName === 'TEXTAREA') dst.textContent = src.value;
  }
  return {html: root.outerHTML, text: root.textContent || ''};
}
"""

CELL_JS = r"""
async ({html, code}) => {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const lines = [];
  const write = (...items) => lines.push(items.map(x =>
    typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
  const output = {log: write, error: write, warn: write};
  try {
    const fn = new (async function(){}).constructor('doc', 'state', 'console', code);
    const result = await fn(doc, window.__codeState, output);
    if (result !== undefined) write(result);
  } catch (error) {
    write(`${error.name}: ${error.message}`);
  }
  return lines.join('\n');
}
"""

CELL_JSON_JS = r"""
async ({html, code}) => {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const fn = new (async function(){}).constructor('doc', 'state', 'console', code);
  const silent = {log() {}, error() {}, warn() {}};
  const result = await fn(doc, window.__codeState, silent);
  return JSON.stringify(result) || '';
}
"""


class CodeKernel:
    def __init__(self, browser):
        self.browser = browser
        self.context = None
        self.page = None
        self.lock = asyncio.Lock()
        self.cells = 0
        self.finishes = 0

    async def _run(self, html: str, code: str, script: str, limit: int) -> str:
        async with self.lock:
            if len(code) > MAX_CODE:
                raise ValueError(f'Code is {len(code)} characters; limit is {MAX_CODE}.')
            if self.cells >= MAX_CELLS:
                raise ValueError(f'Workspace reached its {MAX_CELLS}-cell limit.')
            if self.page is None:
                self.context = await self.browser.new_context(offline=True)
                await self.context.route('**/*', lambda route: route.abort())
                await self.context.route_web_socket('**/*', lambda socket: socket.close())
                self.page = await self.context.new_page()
                await self.page.goto('about:blank')
                await self.page.evaluate('window.__codeState = {}')
            self.cells += 1
            try:
                result = await asyncio.wait_for(
                    self.page.evaluate(script, {'html': html, 'code': code}), CELL_SECONDS)
            except asyncio.TimeoutError:
                await self.close()
                raise ValueError(f'Code cell exceeded {CELL_SECONDS} seconds; workspace reset.')
            if not isinstance(result, str):
                raise ValueError('Code must return a result.')
            if len(result) > limit:
                raise ValueError(f'Code returned {len(result)} characters; limit is {limit}.')
            return result

    async def execute(self, html: str, code: str) -> str:
        try:
            return await self._run(html, code, CELL_JS, MAX_OUTPUT)
        except ValueError as error:
            return str(error)

    async def execute_json(self, html: str, code: str) -> str:
        """Return only the cell's JSON result for a typed output function."""
        return await self._run(html, code, CELL_JSON_JS, MAX_FINAL)

    async def close(self):
        if self.context is not None:
            try:
                await asyncio.wait_for(self.context.close(), 2)
            except Exception:
                pass
        self.context = self.page = None


async def selected_snapshot(session, ref: str) -> dict:
    """Read only the selected current element, preserving its visible text for grounding."""
    async def read():
        async with session.lock:
            await session.revive()
            element = session.page.locator('body') if ref == 'page' else await locate(session.page, ref)
            if element is None:
                raise ValueError(f'No element {ref} on this page; choose a ref from the current view.')
            return await element.evaluate(SNAPSHOT_JS)

    try:
        snapshot = await asyncio.wait_for(read(), SNAPSHOT_SECONDS)
    except asyncio.TimeoutError as error:
        raise ValueError(f'Selected page did not answer within {SNAPSHOT_SECONDS} seconds.') from error
    html = snapshot['html']
    if len(html) > MAX_SNAPSHOT:
        raise ValueError(f'Selected element is {len(html)} characters; choose a smaller ref.')
